fn is_close_i8(a: i8, b: i8, tol: i8) -> bool {
    // Precondition: tol > 0 assumed by problem statement.
    // Calculate difference as i16 to avoid overflow on subtraction.
    let diff = (a as i16) - (b as i16);
    // Check if difference is strictly in (-tol, tol)
    diff > -(tol as i16) && diff < (tol as i16)
}

fn np_isclose(a: Vec<i8>, b: Vec<i8>, tol: i8) -> Vec<bool> {
    // Assume inputs have equal, non-zero length and tol > 0.
    a.into_iter()
        .zip(b.into_iter())
        .map(|(x, y)| is_close_i8(x, y, tol))
        .collect()
}